begin;
-- Required runtime account binding; never run as an unrestricted library sweep.
do $guard$
begin
 perform 1 from public.books where user_id='__TARGET_USER_ID__'::uuid and series_title='化物語' for update;
 if (select count(*) from public.books where user_id='__TARGET_USER_ID__'::uuid and series_title='化物語')<>18
 or (select count(*) from public.books where user_id='__TARGET_USER_ID__'::uuid and series_title='化物語' and isbn is null)<>13
 or (select count(*) from public.books where user_id='__TARGET_USER_ID__'::uuid and series_title='化物語' and volume_number=14 and isbn='9784065245019')<>1
 then raise exception 'Target account or expected 18 books / 13 missing ISBNs / 1 special edition changed'; end if;
end $guard$;
-- Repair only the reported series, owned by an account with the known comic first volume.
