 as r(volume int,title text,isbn text,url text,cover_url text,cover_hash text,published_date text)
), repaired as (
 update public.books b set isbn=o.isbn,
   title=case when b.volume_number=14 and b.isbn='9784065245019' then o.title else b.title end,
   author=coalesce(b.author,'西尾維新, 大暮維人'), publisher=coalesce(b.publisher,'講談社'),
   thumbnail_url=case when b.volume_number=14 and b.isbn='9784065245019' then o.cover_url else coalesce(b.thumbnail_url,o.cover_url) end,
   published_date=coalesce(b.published_date,o.published_date)
 from official o where b.user_id='__TARGET_USER_ID__'::uuid and b.series_title='化物語' and b.volume_number=o.volume
   and (b.isbn is null or (b.volume_number=14 and b.isbn='9784065245019'))
   and exists(select 1 from public.books first_book where first_book.user_id=b.user_id and first_book.series_title='化物語' and first_book.volume_number=1 and first_book.isbn='9784065116173')
   and not exists(select 1 from public.books other where other.user_id=b.user_id and other.isbn=o.isbn and other.id<>b.id)
 returning b.volume_number
)
select set_config('honnoma.repaired_count',count(*)::text,true) repaired_books from repaired;
do $count$ begin if current_setting('honnoma.repaired_count')::int<>14 then raise exception 'Expected exactly 14 repaired rows'; end if; end $count$;
