.kodansha.co.jp/0000370245/5AOX5SBwQGEIJtn6HaXD7PThvgNCG5DDOrInXxiq.jpg", "isbn": "9784065296356", "published_date": "2022-11-17", "cover_hash": "64b81c1afaa07d5a04ff3fe411f1480648b7297ca43f7798716bd3f41855b256"}]$data$::jsonb) loop
   if not exists(select 1 from public.books where user_id='__TARGET_USER_ID__'::uuid and series_title='化物語' and volume_number=(r->>'volume')::int and isbn=r->>'isbn') then continue; end if;
   if exists(select 1 from public.book_content_review_jobs j where j.isbn13=r->>'isbn' and (j.candidate is not null or j.classification_source is not null or j.status not in ('queued','retry'))) then continue; end if;
   candidate:=jsonb_build_object('title',r->>'title','series_title','化物語','volume_number',(r->>'volume')::int,
     'author','西尾維新, 大暮維人','publisher','講談社','description',null,'cover_url',r->>'cover_url','cover_hash',r->>'cover_hash',
     'source_url',r->>'url','provider','publisher','review_origin','registration','release_date',r->>'published_date');
   content_hash:=encode(extensions.digest(convert_to(candidate::text,'UTF8'),'sha256'),'hex');
   perform public.prepare_book_content_review(r->>'isbn',content_hash,candidate);
 end loop;
end $prepare$;
do $check$ begin
 if exists(select 1 from public.books where user_id='__TARGET_USER_ID__'::uuid and series_title='化物語' and isbn is null)
 or not exists(select 1 from public.books where user_id='__TARGET_USER_ID__'::uuid and series_title='化物語' and volume_number=14 and isbn='9784065244814')
 then raise exception 'Repair verification failed'; end if;
end $check$;
commit;
select jsonb_build_object(
 'registered_books',(select count(*) from public.books where user_id='__TARGET_USER_ID__'::uuid and series_title='化物語'),
 'missing_isbn',(select count(*) from public.books where user_id='__TARGET_USER_ID__'::uuid and series_title='化物語' and isbn is null),
 'regular14',(select count(*) from public.books where user_id='__TARGET_USER_ID__'::uuid and series_title='化物語' and volume_number=14 and isbn='9784065244814'),
 'prepared_books',(select count(*) from public.books b join public.book_content_review_jobs j on j.isbn13=b.isbn where b.user_id='__TARGET_USER_ID__'::uuid and b.series_title='化物語' and j.candidate->>'title' is not null),
 'ai_enabled',(select enabled from public.book_content_review_config where id)
) verification;
